#pragma once
#include <cstdint>
namespace kstation {
class MidiWrapperTask final {
public:
 enum class Kind:uint8_t{SysEx,NoopCall,Noop,EmptyDsp,Dsp,Program};enum class Stage:uint8_t{Call,Test,Select,ReadBank,SetBank,WriteBank,ReadProgram,CompareProgram,SelectProgram,CallProgram,Return,AwaitChild,Complete};enum class Child:uint8_t{SysEx,Noop,Dsp,Match,Program};
 explicit MidiWrapperTask(Kind k):kind_(k),stage_((k==Kind::Noop||k==Kind::EmptyDsp)?Stage::Return:Stage::Call){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaitingChild()const{return stage_==Stage::AwaitChild;}Child child()const{return child_;}uint8_t bank()const{return bank_;}uint8_t program()const{return program_;}bool resume(Child c,uint8_t v){if(!awaitingChild()||c!=child_)return false;if(c==Child::Match){match_=v;stage_=Stage::Test;}else stage_=Stage::Return;return true;}
 template<class R,class W>bool advance(R&&r,W&&w){switch(stage_){case Stage::Call:request(kind_==Kind::SysEx?Child::SysEx:kind_==Kind::NoopCall?Child::Noop:kind_==Kind::Dsp?Child::Dsp:Child::Match);break;case Stage::Test:stage_=Stage::Select;break;case Stage::Select:stage_=(match_&0x80)?Stage::Return:Stage::ReadBank;break;case Stage::ReadBank:bank_=uint8_t(r(0xcbff));stage_=Stage::SetBank;break;case Stage::SetBank:stage_=Stage::WriteBank;break;case Stage::WriteBank:w(0xcbff,0xff);stage_=Stage::ReadProgram;break;case Stage::ReadProgram:program_=uint8_t(r(0));stage_=Stage::CompareProgram;break;case Stage::CompareProgram:stage_=Stage::SelectProgram;break;case Stage::SelectProgram:stage_=program_>=100?Stage::Return:Stage::CallProgram;break;case Stage::CallProgram:request(Child::Program);break;case Stage::Return:stage_=Stage::Complete;break;case Stage::AwaitChild:case Stage::Complete:return false;}return true;}
private:void request(Child c){child_=c;stage_=Stage::AwaitChild;}Kind kind_;Stage stage_;Child child_=Child::Noop;uint8_t match_=0,bank_=0,program_=0;
};
class MidiProgramCommitTask final {
public:enum class Stage:uint8_t{TestBank,SelectBank,WriteBank,WriteProgram,Load,Display,Return,AwaitChild,Complete};enum class Child:uint8_t{Load,Display};explicit MidiProgramCommitTask(uint8_t bank):bank_(bank){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaitingChild()const{return stage_==Stage::AwaitChild;}Child child()const{return child_;}bool resume(Child c){if(!awaitingChild()||c!=child_)return false;stage_=c==Child::Load?Stage::Display:Stage::Return;return true;}template<class W>bool advance(W&&w){switch(stage_){case Stage::TestBank:stage_=Stage::SelectBank;break;case Stage::SelectBank:stage_=(bank_&0x80)?Stage::WriteProgram:Stage::WriteBank;break;case Stage::WriteBank:w(0xcd82,true);stage_=Stage::WriteProgram;break;case Stage::WriteProgram:w(0xcd83,false);stage_=Stage::Load;break;case Stage::Load:child_=Child::Load;stage_=Stage::AwaitChild;break;case Stage::Display:child_=Child::Display;stage_=Stage::AwaitChild;break;case Stage::Return:stage_=Stage::Complete;break;case Stage::AwaitChild:case Stage::Complete:return false;}return true;}
private:Stage stage_=Stage::TestBank;Child child_=Child::Load;uint8_t bank_;
};
}
